import{_ as a,o,c as l,a0 as i}from"./chunks/framework.CShDTZbC.js";const p=JSON.parse('{"title":"第 1 章 · 散户为什么亏钱","description":"","frontmatter":{},"headers":[],"relativePath":"book/part1/ch1.md","filePath":"book/part1/ch1.md","lastUpdated":1788537144000}'),e={name:"book/part1/ch1.md"};function r(s,t,c,d,n,h){return o(),l("div",null,[...t[0]||(t[0]=[i('<h1 id="第-1-章-·-散户为什么亏钱" tabindex="-1">第 1 章 · 散户为什么亏钱 <a class="header-anchor" href="#第-1-章-·-散户为什么亏钱" aria-label="Permalink to &quot;第 1 章 · 散户为什么亏钱&quot;">​</a></h1><div class="ob-meta"><span class="chip">第一篇 · 认知篇</span><span class="chip">⏱ 阅读约 20 分钟</span><span class="chip hot">✅ 已发布</span></div><div class="tip custom-block"><p class="custom-block-title">🎯 学完这章你能</p><ul><li>说出散户亏损的三大死穴，并对照诊断出自己的&quot;病灶&quot;</li><li>理解为什么&quot;亏钱不是因为笨，而是因为人性&quot;</li><li>拿到一张可勾选的自我诊断单</li></ul></div><h2 id="_1-1-先看一组扎心的事实" tabindex="-1">1.1 先看一组扎心的事实 <a class="header-anchor" href="#_1-1-先看一组扎心的事实" aria-label="Permalink to &quot;1.1 先看一组扎心的事实&quot;">​</a></h2><p>A 股散户账户的长期收益分布，坊间与学术研究口径不一，但方向高度一致：<strong>多数散户跑输指数，且频繁交易者亏得更快</strong>。原因不神秘——不是智商问题，是<strong>结构问题</strong>：</p><ul><li>你在跟机构拼信息速度、拼执行纪律、拼情绪稳定——三项全输</li><li>而你的&quot;武器&quot;是：刷到的消息、盘面的感觉、大V的口号</li></ul><div class="warning custom-block"><p class="custom-block-title">⚠️ 坑位 0：把股市当提款机</p><p>入市前先问自己：如果这笔钱全部亏完，生活会不会受影响？会影响的钱，不该进市场。这一条不解决，后面不用学了。</p></div><h2 id="_1-2-三大死穴" tabindex="-1">1.2 三大死穴 <a class="header-anchor" href="#_1-2-三大死穴" aria-label="Permalink to &quot;1.2 三大死穴&quot;">​</a></h2><h3 id="死穴一-追涨杀跌-情绪驱动决策" tabindex="-1">死穴一：追涨杀跌（情绪驱动决策） <a class="header-anchor" href="#死穴一-追涨杀跌-情绪驱动决策" aria-label="Permalink to &quot;死穴一：追涨杀跌（情绪驱动决策）&quot;">​</a></h3><p>涨了怕踏空追进去，跌了怕更跌割出来。<strong>买在高点、卖在低点</strong>不是运气差，是情绪行为的必然结果——因为大家都在同一个情绪高点做同样的事。</p><h3 id="死穴二-无系统-决策全靠临场发挥" tabindex="-1">死穴二：无系统（决策全靠临场发挥） <a class="header-anchor" href="#死穴二-无系统-决策全靠临场发挥" aria-label="Permalink to &quot;死穴二：无系统（决策全靠临场发挥）&quot;">​</a></h3><p>买什么、买多少、什么时候卖，每次都不一样。没有固定规则，就意味着每次决策都在被情绪和噪声劫持。<strong>你无法复盘一个不存在的东西</strong>——没有系统，连&quot;我为什么亏&quot;都答不上来。</p><h3 id="死穴三-情绪化持有-赚拿不住-亏扛到底" tabindex="-1">死穴三：情绪化持有（赚拿不住，亏扛到底） <a class="header-anchor" href="#死穴三-情绪化持有-赚拿不住-亏扛到底" aria-label="Permalink to &quot;死穴三：情绪化持有（赚拿不住，亏扛到底）&quot;">​</a></h3><p>小赚就想落袋，小亏就装死装长期投资。结果：盈利单平均持有 10 天，亏损单平均持有 300 天。这是行为金融学里著名的&quot;处置效应&quot;，几乎人人都有，量化系统是解药之一。</p><h2 id="_1-3-量化为什么是对症下药的" tabindex="-1">1.3 量化为什么是对症下药的 <a class="header-anchor" href="#_1-3-量化为什么是对症下药的" aria-label="Permalink to &quot;1.3 量化为什么是对症下药的&quot;">​</a></h2><table tabindex="0"><thead><tr><th>死穴</th><th>量化系统的解法</th></tr></thead><tbody><tr><td>追涨杀跌</td><td>信号规则化：买卖点由数据决定，不由心跳决定</td></tr><tr><td>无系统</td><td>一切可回溯：每笔交易都有据可查，可复盘可迭代</td></tr><tr><td>情绪化持有</td><td>止盈止损机械化：系统执行，不给你反悔的机会</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">💡 人话翻译</p><p>量化不是&quot;更聪明的炒股&quot;，而是<strong>把人性关进系统的笼子</strong>。它不能保证你赚钱——但能保证你亏得明明白白，赚得清清楚楚。</p></div><h2 id="_1-4-自我诊断单" tabindex="-1">1.4 自我诊断单 <a class="header-anchor" href="#_1-4-自我诊断单" aria-label="Permalink to &quot;1.4 自我诊断单&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">📋 对照打勾（诚实一点）</p><ul><li>[ ] 过去一年，我的交易次数超过 20 次</li><li>[ ] 我说不出自己上一笔亏损交易的完整理由</li><li>[ ] 我曾经因为&quot;群里/大V说&quot;而买入</li><li>[ ] 我持有的亏损股超过一年没动过</li><li>[ ] 我没有记账（买入理由、卖出理由、当时情绪）</li><li>[ ] 我用过杠杆或融资</li><li>[ ] 我在盘中做过&quot;当时觉得必须马上&quot;的决定</li><li>[ ] 我不知道自己的年化收益是多少</li></ul><p><strong>≥3 条</strong>：本章就是为你写的。<strong>≥5 条</strong>：这本书就是为你写的。</p></div><h2 id="下一章预告" tabindex="-1">下一章预告 <a class="header-anchor" href="#下一章预告" aria-label="Permalink to &quot;下一章预告&quot;">​</a></h2><p><a href="/book/part1/ch2.html">第 2 章 · 量化到底是什么</a>——既然主观交易这么惨，量化到底凭什么？它真能&quot;量化&quot;人性吗？</p>',21)])])}const b=a(e,[["render",r]]);export{p as __pageData,b as default};
